SELECT product_id FROM product
WHERE product_id > #{lastProductId}
ORDER BY product_id
LIMIT #{limit}

SELECT product_id
FROM product
WHERE state = 'ON_SALE'
  AND expire_at IS NOT NULL
  AND expire_at <= #{before}
LIMIT #{limit}

SELECT product_id
FROM product
WHERE state = 'PENDING_REVIEW'
  AND review_entered_at IS NOT NULL
  AND review_entered_at <= #{before}
LIMIT #{limit}

SELECT 
FROM product p
WHERE p.state = 'ON_SALE'

    AND p.category = #{category}


    AND p.price >= #{minPrice}


    AND p.price <= #{maxPrice}

ORDER BY


    p.price ASC, p.product_id ASC
    p.price DESC, p.product_id DESC
    p.create_time ASC, p.product_id ASC
    p.create_time DESC, p.product_id DESC

LIMIT #{offset}, #{limit}

SELECT 
FROM product p
WHERE p.state = 'ON_SALE'

    AND p.category = #{category}


    AND p.price >= #{minPrice}


    AND p.price <= #{maxPrice}

SELECT product_id, feed_time, create_time, price, view_count
FROM product_feed_index
WHERE state = 'ON_SALE'



            AND (view_count < #{cursor.viewCount}
                OR (view_count = #{cursor.viewCount} AND create_time < #{cursor.createTime})
                OR (view_count = #{cursor.viewCount} AND create_time = #{cursor.createTime}
                    AND product_id < #{cursor.productId}))


            AND (feed_time > #{cursor.feedTime}
                OR (feed_time = #{cursor.feedTime} AND product_id > #{cursor.productId}))


            AND (price > #{cursor.price}
                OR (price = #{cursor.price} AND product_id > #{cursor.productId}))


            AND (price < #{cursor.price}
                OR (price = #{cursor.price} AND product_id < #{cursor.productId}))


            AND (feed_time < #{cursor.feedTime}
                OR (feed_time = #{cursor.feedTime} AND product_id < #{cursor.productId}))



ORDER BY

    view_count DESC, create_time DESC, product_id DESC
    feed_time ASC, product_id ASC
    price ASC, product_id ASC
    price DESC, product_id DESC
    feed_time DESC, product_id DESC

LIMIT #{limit}

SELECT COUNT(1)
FROM product
WHERE state = 'ON_SALE'

    AND category = #{category}


    AND price >= #{minPrice}


    AND price <= #{maxPrice}

SELECT 
FROM product p
WHERE p.user_id = #{userId}
  AND p.state != 'DELETED'
ORDER BY p.create_time DESC, p.product_id DESC
LIMIT #{offset}, #{limit}

SELECT 
FROM product p
WHERE p.user_id = #{userId}
  AND p.state = 'ON_SALE'
ORDER BY p.create_time DESC, p.product_id DESC
LIMIT #{offset}, #{limit}

